IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'spec.test' AND item_code=N'强度测试' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'抗压强度 （裸棒）' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'spec.test', N'强度测试', 60, N'{"v":2,"group":"强度测试","name":"抗压强度 （裸棒）","req":"＞**kgf","method":"将炭棒水平放置在水平压板上，调整间距**mm，设置下压速度5mm/min，按测试键，仪器自动下压，断裂后读取压断时最大力压力值。\n（仪器：普研PY-880）","basis":"银嘉测试标准"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'spec.test' AND item_code=N'强度测试' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'跌落强度 （裸棒）' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'spec.test', N'强度测试', 70, N'{"v":2,"group":"强度测试","name":"跌落强度 （裸棒）","req":"成型强度：高度**cm，垂直跌落3次，炭棒无断裂\n成品强度（一切二）：高度**cm，垂直跌落3次，炭棒无断裂","method":"将活性炭棒放置在**cm高处，3次自由跌落到水泥地板上，测试后，活性炭棒不可有破损现象。","basis":"银嘉测试标准"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'spec.test' AND item_code=N'初始流速及压降测试' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'初始流速' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'spec.test', N'初始流速及压降测试', 80, N'{"v":2,"group":"初始流速及压降测试","name":"初始流速","req":"静态压力0.1Mpa条件下，初始流速＞**L/min","method":"将炭棒组装好装入滤瓶（可旋盖大T），0.1Mpa 静态压力，2 分管路条件下，测试1分钟流量。","basis":"银嘉测试标准"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'spec.test' AND item_code=N'初始流速及压降测试' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'压降' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'spec.test', N'初始流速及压降测试', 90, N'{"v":2,"group":"初始流速及压降测试","name":"压降","req":"测试流速**L/min，压降≤**kpa","method":"将炭棒组装好装入滤瓶（可旋盖大T），滤瓶进出水用2分管直接连接，水流方向外进内出，滤芯前后接装压力表，压力表距离滤芯位置管长为50mm，测试用水纯水/超纯水，水温控制25±1℃，测试流速**L/min，通水10min后记录压差值（滤芯前压-后压）。","basis":"银嘉测试标准"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'spec.test' AND item_code=N'黑水及颗粒物测试 （无黑后）或（无需无黑）' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'初始黑水测试' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'spec.test', N'黑水及颗粒物测试 （无黑后）或（无需无黑）', 100, N'{"v":2,"group":"黑水及颗粒物测试 （无黑后）或（无需无黑）","name":"初始黑水测试","req":"轻微黑水，浊度≤20NTU","method":"将炭棒组装好装入滤瓶（可旋盖大T），按进水方向通水，测试用水为纯水/超纯水，测试流速**±0.1L/min，\n1.初始黑水：用烧杯（白纸垫底部）接第一杯水**ml，观察出水颜色及测试浊度值\n2.浸泡后黑水：冲水10min后，浸泡2H，用烧杯（白纸垫底部）接第一杯出水**mL，目视无肉眼可见黑水，正常照明下，用肉眼观察杯底部颗粒物，颗粒物＜*颗；","basis":"银嘉测试标准"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'spec.test' AND item_code=N'黑水及颗粒物测试 （无黑后）或（无需无黑）' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'浸泡黑水及颗粒物 （裸棒）' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'spec.test', N'黑水及颗粒物测试 （无黑后）或（无需无黑）', 110, N'{"v":2,"group":"黑水及颗粒物测试 （无黑后）或（无需无黑）","name":"浸泡黑水及颗粒物 （裸棒）","req":"浸泡2H：无肉眼可见黑水，浊度≤3NTU\n颗粒物＜6颗","method":"","basis":"银嘉测试标准"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'spec.test' AND item_code=N'黄水测试' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'spec.test', N'黄水测试', 120, N'{"v":2,"group":"黄水测试","name":"","req":"初始：无肉眼可见黄水\n浸泡隔夜（12-16H）：无肉眼可见黄水","method":"将炭棒组装好装入滤瓶（可旋盖大T），按进水方向通水，测试用水为纯水/超纯水，测试流速**±0.1L/min，\n1.初始黄水：用烧杯（白纸垫底部）接第一杯水**ml，观察出水颜色。\n2.浸泡黄水：冲水5min后，炭棒静置浸泡过夜，用烧杯（白纸垫底部）接第一杯出水**mL，观察出水颜色；","basis":"银嘉测试标准"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'spec.test' AND item_code=N'炭棒过滤精度测试' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'一级颗粒物去除率' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'spec.test', N'炭棒过滤精度测试', 130, N'{"v":2,"group":"炭棒过滤精度测试","name":"一级颗粒物去除率","req":"≥**%","method":"将炭棒组装好装入滤瓶（可旋盖大T），滤瓶进出水用2分管直接连接，水流方向外进内出，用纯水/超纯水冲洗30min，冲水流速额定流速*1.5倍，炭棒出水颗粒＜500颗/ml，以纯水/超纯水用A2粉配置加标水0.5-1μm颗粒数10000±1000颗/ml，将冲洗干净的炭棒通过加标水，流速**±0.1L/min，通标2分钟取样测试，计算去除率。","basis":"银嘉测试标准"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'spec.test' AND item_code=N'炭棒过滤精度测试' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'二级颗粒物去除率' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'spec.test', N'炭棒过滤精度测试', 140, N'{"v":2,"group":"炭棒过滤精度测试","name":"二级颗粒物去除率","req":"≥**%","method":"将炭棒组装好装入滤瓶（可旋盖大T），滤瓶进出水用2分管直接连接，水流方向外进内出，用纯水/超纯水冲洗30min，冲水流速额定流速*1.5倍，炭棒出水颗粒＜500颗/ml，以纯水/超纯水用A2粉配置加标水1-5μm颗粒数10000±1000颗/ml，将冲洗干净的炭棒通过加标水，流速**±0.1L/min，通标2分钟取样测试，计算去除率。","basis":"银嘉测试标准"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'spec.test' AND item_code=N'炭棒过滤精度测试' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'浊度去除率' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'spec.test', N'炭棒过滤精度测试', 150, N'{"v":2,"group":"炭棒过滤精度测试","name":"浊度去除率","req":"**%-**%","method":"将炭棒组装好装入滤瓶（可旋盖大T），测试用水为纯水/超纯水，滤瓶进出水用2分管直接连接，测试流速**±0.1L/min，先冲水10min，再进行加标实验；\n以纯水/超纯水加 A2 粉配置浊度为 10-15NTU 的加标溶液，将滤芯与配置好的进水水源相接；通入加标水 5min 后，测试进水、出水浊度；\n平行测试三次，取平均值，并计算浊度去除率。","basis":"银嘉测试标准"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'spec.test' AND item_code=N'隔夜浸泡口感/气味及浊度测试 （无黑后）' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'spec.test', N'隔夜浸泡口感/气味及浊度测试 （无黑后）', 160, N'{"v":2,"group":"隔夜浸泡口感/气味及浊度测试 （无黑后）","name":"","req":"浸泡15-24H：出水无异味、口感正常，浊度值≤3NTU","method":"1）将炭棒组装好装入滤瓶（可旋盖大T），测试用水为纯水/超纯水，测试流速**±0.1L/min，冲水3min后浸泡15-24H，接水量**ml，品尝出水及闻气味，测试浊度值\n品尝人数：至少4人","basis":"银嘉测试标准"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'spec.test' AND item_code=N'浸泡口感测试' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'spec.test', N'浸泡口感测试', 170, N'{"v":2,"group":"浸泡口感测试","name":"","req":"浸泡24H，口感正常无异味","method":"将炭棒组装好装入**工装，按进水方向通RO纯水，测试流速**±0.1L/min,冲水10min后，浸泡24H后，接出水，测试口感\n品尝人数：至少4人","basis":"银嘉测试标准"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'spec.test' AND item_code=N'余氯性能测试' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'初始余氯去除率' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'spec.test', N'余氯性能测试', 180, N'{"v":2,"group":"余氯性能测试","name":"初始余氯去除率","req":"≥98%","method":"将炭棒组装好装入滤瓶（可旋盖大T），滤瓶进出水用2分管直接连接，水流方向外进内出，测试流速**±0.1L/min，用纯水/超纯水采用次氯酸钠原液（有效氯≥10％）稀释后进行余氯去除率的加标试验，余氯浓度控制在2.0±0.2mg/L，通入加标水5min后取样测试，计算去除率。","basis":"银嘉测试标准"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'spec.test' AND item_code=N'余氯性能测试' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'余氯寿命' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'spec.test', N'余氯性能测试', 190, N'{"v":2,"group":"余氯性能测试","name":"余氯寿命","req":"全程加标\n寿命***L，去除率 ≥**%","method":"将炭棒组装好装入滤瓶（可旋盖大T），滤瓶进出水用2分管直接连接，水流方向外进内出，测试流速**±0.1L/min，用纯水/超纯水采用次氯酸钠原液（有效氯≥10％）稀释后进行余氯去除率的加标试验，全程加标/点加标，余氯浓度控制在2.0±0.2mg/L，在寿命终点**L取样测试，计算去除率。","basis":"银嘉测试标准"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'spec.test' AND item_code=N'COD性能测试' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'初始COD去除率' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'spec.test', N'COD性能测试', 200, N'{"v":2,"group":"COD性能测试","name":"初始COD去除率","req":"≥**%","method":"将炭棒组装好装入滤瓶（可旋盖大T），滤瓶进出水用2分管直接连接，水流方向外进内出，先用自来水冲水10min，测试流速**±0.1L/min，用单宁酸加标，浓度控制在3-5mg/L，通入加标水5min后取样测试，计算去除率。","basis":"银嘉测试标准"}', N'seed', SYSDATETIME());
