IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'insp.plan' AND item_code=N'型式检验' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'*碱性性能测试' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'*初始PH增加值测试') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'insp.plan', N'型式检验', 80, N'{"v":2,"group":"型式检验","name":"*碱性性能测试","req":"将炭棒组装好装入伊可普工装，按进水方向通RO纯水（水效水500+RO机），测试流速0.24L/min,冲水5min后，浸泡30min后，测试出水PH，接水量为500ml。\n控制标准：初始PH增加值＞3.0","method":"常规抽检","quality":"*初始PH增加值测试","instrument":"PH计","inspect":"IQC","measure":"1. 暂停该批次继续生产，隔离已生产不合格品，防止流入下工序\n2. 复核检验方法、量具、标准，确认是否误判\n3. 扩大抽检比例，判定问题是偶发还是批量性","freq":"每批次","sampling":"1PCS/一个生产批次","content":"检验炭棒初始PH增加值测试是否符合要求"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'insp.plan' AND item_code=N'型式检验' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'*碱性性能测试' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'*浸泡24H口感测试') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'insp.plan', N'型式检验', 90, N'{"v":2,"group":"型式检验","name":"*碱性性能测试","req":"将炭棒组装好装入伊可普工装，按进水方向通RO纯水（水效水500+RO机），测试流速0.24L/min,冲水5min后，浸泡24H后，接出水（连续接五杯，接水量为100ml）及原水，测试口感、PH、TDS\n控制标准：1.五杯口感均无异常\n2.第一杯TDS增加值小于150\n3.第一杯出水PH增加值＞4.0","method":"常规抽检","quality":"*浸泡24H口感测试","instrument":"PH计、TDS笔","inspect":"IQC","measure":"1. 暂停该批次继续生产，隔离已生产不合格品，防止流入下工序\n2. 复核检验方法、量具、标准，确认是否误判\n3. 扩大抽检比例，判定问题是偶发还是批量性","freq":"每批次","sampling":"1PCS/一个生产批次","content":"检验浸泡24H口感测试是否符合要求"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'insp.plan' AND item_code=N'型式检验' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'*碱性性能测试' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'碱性寿命') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'insp.plan', N'型式检验', 100, N'{"v":2,"group":"型式检验","name":"*碱性性能测试","req":"将炭棒组装好装入伊可普工装，全程RO纯水（水效水500+RO机）加标测试控制水温25±3℃、流速0.24L/min，在额定净水0%、25%、50%、75%、100%，浸泡30min后取炭棒滤后水进行测试记录节点流速及炭棒出水PH（寿命1000L，每天冲水约145L，测试周期约为7天）。寿命1000L，PH增加值≥0.5","method":"型式检测报告","quality":"碱性寿命","instrument":"PH计","inspect":"IQC","measure":"1. 暂停该批次继续生产，隔离已生产不合格品，防止流入下工序\n2. 复核检验方法、量具、标准，确认是否误判\n3. 扩大抽检比例，判定问题是偶发还是批量性","freq":"型式检验半年一次","sampling":"","content":"检验炭棒碱性寿命测试是否符合要求"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'insp.plan' AND item_code=N'型式检验' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'余氯性能测试' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'*余氯初始去除率') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'insp.plan', N'型式检验', 110, N'{"v":2,"group":"型式检验","name":"余氯性能测试","req":"将炭棒组装好装入单筒，滤瓶进出水用2分直接连接，水流方向外进内出，测试流速0.24L/min，采用次氯酸钠原液（有效氯≥10％）稀释后进行余氯去除率的加标试验，余氯浓度控制在2.0±0.2mg/L，，通入加标水5min后取样测试，计算去除率。\n控制标准：余氯初始去除率≥99%","method":"常规抽检","quality":"*余氯初始去除率","instrument":"哈希DR3900","inspect":"IQC","measure":"1. 暂停该批次继续生产，隔离已生产不合格品，防止流入下工序\n2. 复核检验方法、量具、标准，确认是否误判\n3. 扩大抽检比例，判定问题是偶发还是批量性","freq":"每批次","sampling":"1PCS/一个生产批次","content":"检验初始余氯去除率是否符合要求"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'insp.plan' AND item_code=N'型式检验' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'余氯性能测试' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'余氯寿命测试') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'insp.plan', N'型式检验', 120, N'{"v":2,"group":"型式检验","name":"余氯性能测试","req":"将炭棒组装好装入单筒，滤瓶进出水用2分直接连接，水流方向外进内出，测试流速0.24L/min，采用次氯酸钠原液（有效氯≥10％）稀释后进行余氯去除率的加标试验，余氯浓度控制在2.0±0.2mg/L，在额定净水0%、25%、50%、75%、100%进行取样测试。全程加标，寿命1000L， 去除率≥90%","method":"型式检测报告","quality":"余氯寿命测试","instrument":"哈希DR3900","inspect":"IQC","measure":"1. 暂停该批次继续生产，隔离已生产不合格品，防止流入下工序\n2. 复核检验方法、量具、标准，确认是否误判\n3. 扩大抽检比例，判定问题是偶发还是批量性","freq":"型式检验半年一次","sampling":"","content":"检验炭棒余氯寿命测试是否符合要求"}', N'seed', SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM yj_std_lib WHERE lib_code=N'insp.plan' AND item_code=N'型式检验' AND ISNULL(JSON_VALUE(content,'$.name'),N'')=N'卫生浸泡' AND ISNULL(JSON_VALUE(content,'$.quality'),N'')=N'/') INSERT INTO yj_std_lib (lib_code, item_code, seq, content, asp_user1, asp_time1) VALUES (N'insp.plan', N'型式检验', 130, N'{"v":2,"group":"型式检验","name":"卫生浸泡","req":"符合《生活饮用水输配水设备及防护材料卫生安全评价规范》","method":"型式检测报告","quality":"/","instrument":"/","inspect":"IQC","measure":"1. 暂停该批次继续生产，隔离已生产不合格品，防止流入下工序\n2. 复核检验方法、量具、标准，确认是否误判\n3. 扩大抽检比例，判定问题是偶发还是批量性","freq":"型式检验半年一次","sampling":"","content":"检验炭棒浸泡安全是否符合要求"}', N'seed', SYSDATETIME());
SELECT lib_code, COUNT(*) AS total_rows, SUM(CASE WHEN asp_user1=N'seed' THEN 1 ELSE 0 END) AS seed_rows FROM yj_std_lib WHERE lib_code IN (N'spec.test', N'insp.plan') GROUP BY lib_code;
